StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			UV Data - Ultra Aqua
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			Ultra Aqua UV system - ModbusTCP option                                                                                                                                                                                                                                                                                                                          
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-07-14		William Veim			Initial release              
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
Inp_Request[0].Enable :=TRUE;
Inp_Request[0].NodeAdr := 1;
Inp_Request[0].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[0].Read.StartAddressLocal :=		0;
Inp_Request[0].Read.StartAddressRemote := 	0;
Inp_Request[0].Read.Count := 						15;

Inp_Request[1].Enable :=TRUE;
Inp_Request[1].NodeAdr := 1;
Inp_Request[1].FunctionCode := eFun#Fn16_WriteMultipleRegisters;
Inp_Request[1].Write.StartAddressLocal := 	15;
Inp_Request[1].Write.StartAddressRemote :=  50;
Inp_Request[1].Write.Count := 						 2; 

(*************************************************************************
 *	INTERNAL VARIABLE CONTROL
 *************************************************************************)
 
Ext_UV_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
RE_Startup(Clk:=WORD_TO_INT(Inp_HoldingRegister[7]) > 0);

//Communication state
IF Inp_Request[0].Status.Success AND NOT Inp_Request[0].Status.Error THEN
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

CASE  WORD_TO_UINT(Inp_HoldingRegister[7]) OF
	
	0: //Stopped
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Stopped';
		
	1: //Waiting to start
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Waiting to start';
		
	2: //Starting
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Starting';
		
	3: //Lamps on but not warmed up
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Warming up lamps';
		
	4: //Lamps warmed up & flow relay active
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Lamps warmed up and flow ready';
		
	5: //Lamp fully warmed up and ready to be dimmed
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Normal operation';
	
END_CASE;

Ext_UV_Data.EXT_Operator.LocalOperation:=			WORD_TO_UINT(Inp_HoldingRegister[10]) = 0 OR WORD_TO_UINT(Inp_HoldingRegister[10]) = 1;
Ext_UV_Data.EXT_Operator.CountDown:= 				INT#-1; //Invisible/not available
Ext_UV_Data.EXT_Operator.DoseLevel:= 				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[0], UnvalidValue:=16#FFFF);
Ext_UV_Data.EXT_Operator.FlowRate:=					HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[5], UnvalidValue:=16#FFFF);
Ext_UV_Data.EXT_Operator.IntensityLevel:=			HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[4], UnvalidValue:=16#FFFF);
Ext_UV_Data.EXT_Operator.PowerLevel:=				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[1], UnvalidValue:=16#FFFF);
Ext_UV_Data.EXT_Operator.Temperature:=				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[3], UnvalidValue:=16#FFFF);

Ext_UV_Data.EXT_Statistics.OperatingTime:=			WORD_TO_LINT(Inp_HoldingRegister[2]);
Ext_UV_Data.EXT_Statistics.PowerConsuption:=		REAL#-1;
Ext_UV_Data.EXT_Statistics.WipingCycles:=			LINT#-1;
IF RE_Startup.Q THEN
	Ext_UV_Data.EXT_Statistics.StartCycles:=	 Ext_UV_Data.EXT_Statistics.StartCycles + 1;
END_IF;

//OUTPUT DATA
OutABit(InOut:=Inp_HoldingRegister[15], Pos:=0, BitVal:=Ext_UV_Data.EXT_Operator.SystemStart AND (Cfg_Interlock_InUse AND NOT Inp_Interlock));
OutABit(InOut:=Inp_HoldingRegister[15], Pos:=1, BitVal:=Ext_UV_Data.EXT_Operator.ResetFault);

IF Cfg_FlowInUse THEN
	Inp_HoldingRegister[16]:=REAL_TO_WORD(Inp_Flowrate);
END_IF;

(*************************************************************************
 *	ALARM/FAULT STATUS
 *************************************************************************)

Wrk_State[1]:=NOT Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=0) OR TestABit(In:=Inp_HoldingRegister[13], Pos:=1);
Wrk_Suffix[2]:='Service requierd';
Wrk_State[3]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=2);
Wrk_Suffix[3]:='Driver faulted';
Wrk_State[4]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=3);
Wrk_Suffix[4]:='Lamp faulted';
Wrk_State[5]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=4);
Wrk_Suffix[5]:='General alarm';
Wrk_State[6]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=5);
Wrk_Suffix[6]:='Critical alarm';
Wrk_State[7]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=6);
Wrk_Suffix[7]:='Alarm';
Wrk_State[8]:=TestABit(In:=Inp_HoldingRegister[13], Pos:=7);
Wrk_Suffix[8]:='Pre-alarm';
Wrk_State[9]:=FALSE;
Wrk_Suffix[9]:='';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_UV_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_UV_Data.EXT_Engineering, 
						Ext_General:=					Ext_UV_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= 			FB_Data_Logic.Sts_AlarmTriggered;
 Out_FlowReady:= 	TestABit(In:=Inp_HoldingRegister[8], Pos:=2);

 //STRUCTURE
 Ext_UV_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ConnCab;
 Ext_UV_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_UV_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
